<template><div class="page"><el-form :model="query" inline><el-form-item :label="t('memberAccount')"><el-input v-model="query.loginName" clearable /></el-form-item><el-form-item :label="t('role')"><el-select v-model="query.roleCode" clearable><el-option label="BD Leader" value="BD_LEADER"/><el-option label="BD" value="BD"/></el-select></el-form-item><el-form-item :label="t('status')"><el-select v-model="query.status" clearable><el-option :label="t('normal')" value="0"/><el-option :label="t('disabled')" value="1"/></el-select></el-form-item><el-button type="primary" @click="load">{{ t('query') }}</el-button><el-button @click="reset">{{ t('reset') }}</el-button></el-form><div class="bar"><h2>{{ t('myTeam') }}</h2><el-button v-if="canCreate" type="primary" @click="visible=true">{{ t('addSubordinate') }}</el-button></div><el-table :data="rows" v-loading="loading" border><el-table-column prop="realName" :label="t('member')"/><el-table-column prop="loginName" :label="t('account')"/><el-table-column :label="t('role')"><template #default="{row}">{{ role(row.roleCode) }}</template></el-table-column><el-table-column prop="parentLoginName" :label="t('parentAccount')"/><el-table-column prop="directSubordinateCount" :label="t('directSubordinates')"/><el-table-column prop="guildCount" :label="t('teamGuilds')"/><el-table-column prop="monthFlow" :label="`${t('monthlyFlow')} (${t('coins')})`"/><el-table-column :label="t('status')"><template #default="{row}">{{row.status==='0'?t('normal'):t('disabled')}}</template></el-table-column><el-table-column :label="t('openingMethod')"><template #default="{row}">{{ openMethod(row.openMethod) }}</template></el-table-column><el-table-column prop="createTime" :label="t('openingTime')"/></el-table><pagination v-show="total>0" v-model:page="query.pageNum" v-model:limit="query.pageSize" :total="total" @pagination="load"/><el-dialog v-model="visible" :title="t('addSubordinate')" width="520px"><el-form ref="formRef" :model="form" :rules="rules" label-width="110px"><el-form-item :label="t('role')" prop="roleCode"><el-radio-group v-model="form.roleCode"><el-radio v-for="item in roles" :key="item.value" :label="item.value">{{item.label}}</el-radio></el-radio-group></el-form-item><el-form-item :label="t('name')" prop="realName"><el-input v-model="form.realName"/></el-form-item><el-form-item :label="t('account')" prop="loginName"><el-input v-model="form.loginName"/></el-form-item><el-form-item :label="t('linkedWohaId')" prop="wohaChatNo"><el-input v-model.number="form.wohaChatNo"/></el-form-item><el-form-item :label="t('whatsapp')"><el-input v-model="form.whatsapp"/></el-form-item><el-form-item :label="t('description')"><el-input v-model="form.remark" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="visible=false">{{ t('cancel') }}</el-button><el-button type="primary" @click="submit">{{ t('confirmAdd') }}</el-button></template></el-dialog></div></template>
<script setup>import { addExternalSubordinate,getExternalProfile,listExternalTeamMembers } from '@/api/external/manager';import { ElMessageBox } from 'element-plus';import { useExternalI18n } from '@/i18n/external';const { t }=useExternalI18n();const rows=ref([]),total=ref(0),loading=ref(false),visible=ref(false),formRef=ref(),profile=ref({}),query=reactive({pageNum:1,pageSize:10,loginName:'',roleCode:'',status:''}),form=reactive({roleCode:'BD',realName:'',loginName:'',wohaChatNo:undefined,whatsapp:'',remark:''}),rules={roleCode:[{required:true,message:t('selectRole')}],realName:[{required:true,message:t('enterName')}],loginName:[{required:true,message:t('enterAccount')}],wohaChatNo:[{required:true,message:t('enterUserWohaId')}]};const canCreate=computed(()=>profile.value.permissions?.includes('CREATE_SUBORDINATE')&&profile.value.roleCode!=='BD');const roles=computed(()=>profile.value.roleCode==='SUPER_ADMIN'?[{value:'BD_LEADER',label:'BD Leader'},{value:'BD',label:'BD'}]:[{value:'BD',label:'BD'}]);const role=v=>v==='BD_LEADER'?'BD Leader':v==='BD'?'BD':v;const openMethod=v=>v==='OPERATION_OPEN'?t('operationOpen'):v==='SUBORDINATE_OPEN'?t('subordinateOpen'):v;async function load(){loading.value=true;try{const r=await listExternalTeamMembers(query);rows.value=r.rows;total.value=r.total}finally{loading.value=false}}function reset(){Object.assign(query,{pageNum:1,loginName:'',roleCode:'',status:''});load()}function submit(){formRef.value.validate(async ok=>{if(!ok)return;const r=await addExternalSubordinate(form);visible.value=false;await ElMessageBox.alert(`${t('account')}：${form.loginName}<br>${t('initialPassword')}：${r.initialPassword}`,t('accountCreated'),{dangerouslyUseHTMLString:true});load()})}getExternalProfile().then(r=>profile.value=r.data);load()</script>
<style scoped>
.page{padding:20px}.bar{display:flex;align-items:center;justify-content:space-between}.bar h2{font-size:18px}
.page :deep(.pagination-container) {
  display: flex;
  justify-content: flex-end;
  height: auto;
  margin: 12px 0 0;
  padding: 0 !important;
  background: transparent;
}
.page :deep(.pagination-container .el-pagination) {
  position: static;
}
</style>
